import{_ as d,a0 as o,w as n,s as p,I as a,x as i,a1 as u,A as r,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中使用 Audacity 錄製音頻（並降噪） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 Audacity 錄製音頻（並降噪） | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 Audacity 錄製音頻（並降噪） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 Audacity 錄製音頻（並降噪） | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20220814 How to Record Audio in Linux With Audacity -and Reduce Noise-","title":"如何在 Linux 中使用 Audacity 錄製音頻（並降噪）","tag":"202211","desc":""},"relativePath":"202211/20220814 How to Record Audio in Linux With Audacity -and Reduce Noise-.md","filePath":"[post].md"}'),l={name:"202211/20220814 How to Record Audio in Linux With Audacity -and Reduce Noise-.md"};function y(f,t,b,g,c,m){const s=o("Link");return n(),p("div",null,[t[26]||(t[26]=a("h1",{id:"如何在-linux-中使用-audacity-錄製音頻-並降噪",tabindex:"-1"},[i("如何在 Linux 中使用 Audacity 錄製音頻（並降噪） "),a("a",{class:"header-anchor",href:"#如何在-linux-中使用-audacity-錄製音頻-並降噪","aria-label":"Permalink to “如何在 Linux 中使用 Audacity 錄製音頻（並降噪）”"},"​")],-1)),t[27]||(t[27]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/24/114858g6vpfg3gfglvxnp4.jpg",alt:""})],-1)),a("p",null,[u(s,{href:"https://github.com/audacity/audacity"},{default:r(()=>[...t[0]||(t[0]=[i("Audacity",-1)])]),_:1}),t[2]||(t[2]=i(" 是一個自由開源的跨平台 ",-1)),u(s,{href:"https://itsfoss.com/best-audio-editors-linux/"},{default:r(()=>[...t[1]||(t[1]=[i("音頻編輯器",-1)])]),_:1}),t[3]||(t[3]=i("。專業人士使用它是因為它提供的功能僅需安裝很小的軟件包。",-1))]),t[28]||(t[28]=e('<p>你不必成為一名專業人士並使用它的所有功能。你可以使用它從麥克風錄製音頻，並執行一些基本操作，如背景噪聲消除。</p><p>我將在本教程中向你展示如何做到這一點。</p><h3 id="在-linux-上安裝-audacity" tabindex="-1">在 Linux 上安裝 Audacity <a class="header-anchor" href="#在-linux-上安裝-audacity" aria-label="Permalink to “在 Linux 上安裝 Audacity”">​</a></h3><p>在 Linux 上安裝 Audacity 是一個非常簡單的過程。由於其受歡迎，可以在大多數 Linux 發行版的官方存儲庫中找到它。</p><p>你可以在發行版的軟件中心或軟件包管理器中搜索它。</p><p>作為一個終端愛好者，讓我分享一下常見發行版的命令。</p><p>對於基於 Debian 或 Ubuntu 的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install audacity</span></span></code></pre></div><p>對於基於 RHEL 或 Fedora 的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install audacity</span></span></code></pre></div><p>如果你在用基於 Arch 的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Syu audacity</span></span></code></pre></div>',12)),a("p",null,[t[5]||(t[5]=a("strong",null,"注意",-1)),t[6]||(t[6]=i("，通過官方存儲庫安裝可能無法獲得 ",-1)),u(s,{href:"https://github.com/audacity/audacity/releases"},{default:r(()=>[...t[4]||(t[4]=[i("最新版本",-1)])]),_:1}),t[7]||(t[7]=i("。要獲得最新版本，你可以使用 AppImage 或 Flatpak/Snap 軟件包。",-1))]),t[29]||(t[29]=e('<h3 id="使用-audacity-錄製音頻" tabindex="-1">使用 Audacity 錄製音頻 <a class="header-anchor" href="#使用-audacity-錄製音頻" aria-label="Permalink to “使用 Audacity 錄製音頻”">​</a></h3><p>安裝 Audacity 後，從應用程序菜單打開它或從終端啓動它。你會看到這樣的界面：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-interface.png" alt="Audacity Interface"></p><p>單擊“錄製”按鈕（紅點）即可輕鬆開始錄製。完成後，單擊“ 停止”按鈕（方形圖標）來結束錄製。你還可以預覽錄製的波形，如下所示：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/record-audio-with-audacity.png" alt="record audio with audacity"></p><p>然後，你可以通過單擊“播放”按鈕（綠色圖標）檢查錄製的內容。</p><p>如果你沒有看到任何波形，則表示未錄製到任何內容。很可能，你沒有正確設置音頻輸入。確保你選擇了正確的麥克風，並確保在“<ruby>系統設置<rt>system settings</rt></ruby>”中其未被靜音。你也可以通過 Audacity 接口設置。</p><p>錄音不會自動保存為 MP3 或其他格式。<strong>要保存錄音</strong>，你可以轉到 “<ruby>文件<rt>File</rt></ruby> → <ruby>導出<rt>Export</rt></ruby>” 並選擇 “<ruby>導出為 MP3<rt>Export as MP3</rt></ruby>”（或任何其他想要的格式）。</p><h3 id="使用-audacity-降低背景噪聲" tabindex="-1">使用 Audacity 降低背景噪聲 <a class="header-anchor" href="#使用-audacity-降低背景噪聲" aria-label="Permalink to “使用 Audacity 降低背景噪聲”">​</a></h3><p>Audacity 還有另一個很棒的功能，你可以使用它來減少錄製音頻中的白噪聲。</p><p>最好的做法是在開始使用 Audacity 錄製時的前五秒不要説任何話。這將為你提供所需的背景噪聲。</p><p>在錄製音頻的波形上，選擇你認為是背景噪聲的部分。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-noise-reduction.png" alt="Background noise"></p><p>選擇噪聲部分後，從頂部文件菜單中轉到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”。</p><p>它會像這樣打開一個彈出窗口。單擊此處的 “<ruby>獲取噪音配置文件<rt>Get Noise Profile</rt></ruby>”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-noise-steps.png" alt="Noise Reduction Effect Popup Window"></p><p>現在，你已經設置了噪聲配置文件。現在，你必須使用它來減少錄音中的噪聲。</p><p>按 <code>Ctrl + A</code> 快捷鍵選擇整段錄音。你也可以選擇其中的一部分，僅對所選部分減少噪聲。</p><p>選擇音軌後，再次轉到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”。</p><p><strong>這次不要單擊</strong> “<ruby>獲取噪音配置文件<rt>Get Noise Profile</rt></ruby>”。這一次，你應該能夠按下 “OK” 按鈕。</p><p>只需按下 “OK” 按鈕，即可將降噪效果應用到錄音中，並反映在波形上，如下所示：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audacity-noise-reduced.png" alt="Audio Waveform after Noise Reduction"></p><p>現在，相較而言，錄製的音頻將具有更少的噪聲。你可以在選擇 “<ruby>降低噪音<rt>Noise Reduction</rt></ruby>” 效果時微調噪聲過濾。</p><p>總結如下：</p><ul><li>選擇噪聲部分，轉到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”，然後單擊 “<ruby>獲取噪音配置文件<rt>Get Noise Profile</rt></ruby>”</li><li>按 <code>Ctrl + A</code> 選擇整段音頻錄製，轉到 “<ruby>效果<rt>Effects</rt></ruby> → <ruby>降低噪音<rt>Noise Reduction</rt></ruby>”，這次按 <code>OK</code> 按鈕</li></ul><p>請注意，你無法移除所有類型的噪聲，但這應該會有所幫助。</p><h3 id="audacity-能做更多事情" tabindex="-1">Audacity 能做更多事情 <a class="header-anchor" href="#audacity-能做更多事情" aria-label="Permalink to “Audacity 能做更多事情”">​</a></h3><p>使用 Audacity 錄製音頻可能不像使用 GNOME 錄音機那樣簡單，但它並不太複雜。如果你正在錄製畫外音，降噪功能將非常有用。</p><p>Audacity 有更多其他功能，不可能在一個教程中涵蓋所有這些功能。這就是為什麼我會保持簡短的原因。</p>',29)),a("p",null,[t[9]||(t[9]=i("如果你不能接受 2021 年的 ",-1)),u(s,{href:"https://news.itsfoss.com/audacity-fiasco-fork/"},{default:r(()=>[...t[8]||(t[8]=[i("Audacity 的隱私政策調整",-1)])]),_:1}),t[10]||(t[10]=i("，試試其他可用的工具。",-1))]),t[30]||(t[30]=a("p",null,"我希望這個小教程能幫助你使用 Audacity 進行音頻錄製。如果你有問題或建議，請告訴我。",-1)),t[31]||(t[31]=a("hr",null,null,-1)),a("p",null,[t[12]||(t[12]=i("via: ",-1)),u(s,{href:"https://itsfoss.com/audacity-recording/"},{default:r(()=>[...t[11]||(t[11]=[i("https://itsfoss.com/audacity-recording/",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=i("作者：",-1)),u(s,{href:"https://itsfoss.com/author/anuj/"},{default:r(()=>[...t[13]||(t[13]=[i("Anuj Sharma",-1)])]),_:1}),t[18]||(t[18]=i(" 選題：",-1)),u(s,{href:"https://github.com/lkxed"},{default:r(()=>[...t[14]||(t[14]=[i("lkxed",-1)])]),_:1}),t[19]||(t[19]=i(" 譯者：",-1)),u(s,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:r(()=>[...t[15]||(t[15]=[i("FYJNEVERFOLLOWS",-1)])]),_:1}),t[20]||(t[20]=i(" 校對：",-1)),u(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=i("本文由 ",-1)),u(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[i("LCTT",-1)])]),_:1}),t[24]||(t[24]=i(" 原創編譯，",-1)),u(s,{href:"https://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[i("Linux中國",-1)])]),_:1}),t[25]||(t[25]=i(" 榮譽推出",-1))])])}const k=d(l,[["render",y]]);export{x as __pageData,k as default};
